def canonical_common_policy_marker_for_test() -> dict[str, object]:
    common = (
        Path(server_module.__file__).with_name("markdown") / "common.md"
    ).read_bytes()
    header = common.splitlines()[0]
    prefix = b"<!-- codex-master-common-policy:"
    suffix = b" -->"
    metadata = json.loads(header[len(prefix) : -len(suffix)].decode("ascii"))
    return {
        "schema_version": metadata["schema_version"],
        "generation": metadata["generation"],
        "digest": hashlib.sha256(common).hexdigest(),
    }


def rewrite_fleet_marker_for_test(
    home: Path,
    mutate: Any,
) -> dict[str, Any]:
    marker_path = home / server_module.FLEET_AGENT_MARKER_FILE
    marker = json.loads(marker_path.read_text(encoding="utf-8"))
    mutate(marker)
    marker_path.write_text(
        json.dumps(marker, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return marker


def managed_home_tree_for_test(home: Path) -> dict[str, tuple[str, int, bytes | None]]:
    """Snapshot observable managed-home contents for transaction rollback tests."""

    result: dict[str, tuple[str, int, bytes | None]] = {}
    for path in (home, *sorted(home.rglob("*"))):
        current = path.lstat()
        relative = "" if path == home else path.relative_to(home).as_posix()
        if stat.S_ISDIR(current.st_mode):
            result[relative] = ("directory", stat.S_IMODE(current.st_mode), None)
        else:
            result[relative] = ("file", stat.S_IMODE(current.st_mode), path.read_bytes())
    return result


def fleet_identity_snapshot_for_test(path: Path) -> tuple[tuple[int, ...], str | None]:
    current = path.lstat()
    digest = hashlib.sha256(path.read_bytes()).hexdigest() if stat.S_ISREG(current.st_mode) else None
    return server_module._fleet_snapshot_metadata(current), digest


def fleet_identity_journal_prepare_for_test(
    parent_fd: int,
    home_fd: int,
    parent_snapshot: tuple[int, ...],
    home_snapshot: tuple[int, ...],
    entries: tuple[server_module._FleetIdentityJournalEntry, ...],
    *,
    faultpoint: Any = None,
) -> server_module._FleetIdentityJournal:
    plan = make_fleet_identity_journal_plan(
        uuid.uuid4().hex,
        tuple(
            (entry.name, entry.before is not None, entry.replacement_kind is not None)
            for entry in entries
        ),
    )
    prepare = server_module._fleet_identity_journal_prepare
    return prepare(
        parent_fd,
        home_fd,
        parent_snapshot,
        home_snapshot,
        entries,
        plan,
        faultpoint=faultpoint,
    )


@contextlib.contextmanager
def fleet_identity_home_fds_for_test(
    tmp: str,
) -> Iterator[
    tuple[
        Path,
        Path,
        int,
        int,
        list[server_module._FleetIdentityJournal],
    ]
]:
    parent = Path(tmp) / "pool"
    home = parent / "a1"
    parent.mkdir(mode=0o700)
    home.mkdir(mode=0o700)
    parent_fd = os.open(parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    home_fd = os.open(home, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    journals: list[server_module._FleetIdentityJournal] = []
    try:
        yield parent, home, parent_fd, home_fd, journals
    finally:
        for journal in reversed(journals):
            if journal.fd >= 0:
                os.close(journal.fd)
                journal.fd = -1
        os.close(home_fd)
        os.close(parent_fd)


def write_legacy_home_refresh_for_test(
    root: Path,
    *,
    config: str,
) -> tuple[Path, server_module.AgentDescriptor, server_module.InventorySnapshot]:
    """Create a stopped A3-style home with only wrapper/config digest drift."""

    pool, legacy_descriptor, legacy_inventory = write_managed_class_home_for_test(root, agent="a3")
    descriptor = dataclass_replace(
        legacy_descriptor,
        model="gpt-5.6-luna",
        skill_profile="generic",
    )
    inventory = dataclass_replace(
        legacy_inventory,
        agents={descriptor.agent_id: descriptor},
    )
    home = descriptor.home
    marker_path = home / server_module.FLEET_AGENT_MARKER_FILE
    marker = json.loads(marker_path.read_text(encoding="utf-8"))
    marker.pop("runtime_skill_profile", None)
    marker["model"] = "gpt-5.4-mini"
    marker_path.write_text(json.dumps(marker, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    wrapper = "\n".join(
        [
            "#!/usr/bin/env bash",
            "set -euo pipefail",
            "",
            f'export CODEX_HOME="{server_module.pool_shell_double_content(str(home))}"',
            'if [[ -z "${CODEX_AGENT_BIN:-}" ]]; then',
            f"  CODEX_AGENT_BIN={server_module.shlex.quote(str(root / 'codex-native'))}",
            "fi",
            "export CODEX_AGENT_BIN",
            "unset CODEX_ACCESS_TOKEN OPENAI_API_KEY",
            'exec taskset --cpu-list 4-10 /usr/bin/env -- "${CODEX_AGENT_BIN}" "$@"',
            "",
        ]
    )
    (home / "codex").write_text(wrapper, encoding="utf-8")
    (home / "config.toml").write_text(config, encoding="utf-8")
    return pool, descriptor, inventory


def write_trusted_codex_coordinator_plugin_for_test(codex_home: Path) -> Path:
    """Install the exact Codex Coordinator hook manifest used by the live pool."""

    plugin_root = (
        codex_home
        / "plugins"
        / "cache"
        / "openai-curated-remote"
        / "codex-coordinator"
    )
    version_root = plugin_root / "0.4.0"
    (version_root / ".codex-plugin").mkdir(parents=True)
    (version_root / "hooks").mkdir()
    (plugin_root / ".codex-remote-plugin-install.json").write_text(
        json.dumps(
            {
                "schema_version": 1,
                "remote_plugin_id": "plugins_6a5c8cb6a5648191a43a76e6a1e637d8",
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    (version_root / ".codex-plugin" / "plugin.json").write_text(
        json.dumps(
            {
                "name": "codex-coordinator",
                "version": "0.4.0",
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    (version_root / "hooks" / "hooks.json").write_text(
        """{
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume|clear|compact",
        "hooks": [
          {
            "type": "command",
            "command": "python3 -I \\\"${PLUGIN_ROOT}/scripts/codex_coordinator_session_start.py\\\"",
            "commandWindows": "python -I \\\"${PLUGIN_ROOT}/scripts/codex_coordinator_session_start.py\\\"",
            "timeout": 5,
            "statusMessage": "Checking the Codex task-boundary board"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "python3 -I \\\"${PLUGIN_ROOT}/scripts/codex_coordinator_stop_guard.py\\\"",
            "commandWindows": "python -I \\\"${PLUGIN_ROOT}/scripts/codex_coordinator_stop_guard.py\\\"",
            "timeout": 5
          }
        ]
      }
    ]
  }
}
""",
        encoding="utf-8",
    )
    return version_root


def write_static_codex_package_for_test(root: Path) -> tuple[Path, Path, Path]:
    """Create npm-style static metadata, launcher, and one native Codex ELF."""

    triple = "x86_64-unknown-linux-musl"
    package_name = "codex-linux-x64"
    package_root = root / "codex-package"
    launcher = package_root / "bin" / "codex.js"
    vendor_root = package_root / "node_modules" / "@openai" / package_name / "vendor" / triple
    native = vendor_root / "bin" / "codex"
    launcher.parent.mkdir(parents=True)
    native.parent.mkdir(parents=True)
    launcher.write_text("#!/usr/bin/env node\nprocess.exit(99);\n", encoding="utf-8")
    launcher.chmod(0o700)
    (package_root / "package.json").write_text(
        json.dumps(
            {
                "name": "@openai/codex",
                "bin": {"codex": "bin/codex.js"},
                "optionalDependencies": {f"@openai/{package_name}": "test"},
            }
        ),
        encoding="utf-8",
    )
    (vendor_root / "codex-package.json").write_text(
        json.dumps({"layoutVersion": 1, "target": triple, "variant": "codex", "entrypoint": "bin/codex"}),
        encoding="utf-8",
    )
    shutil.copyfile(sys.executable, native)
    native.chmod(0o700)
    launcher_link = root / "codex-cli"
    launcher_link.symlink_to(launcher)
    return launcher_link, native, vendor_root


@contextlib.contextmanager
def root_owned_static_codex_package_for_test(root: Path, *, foreign_paths: set[Path] | None = None):
    """Model root-owned installed metadata without a privileged test process."""

    foreign_paths = foreign_paths or set()
    real_lstat = Path.lstat
    real_fstat = server_module.os.fstat

    def root_owned(metadata: os.stat_result) -> SimpleNamespace:
        return SimpleNamespace(
            st_mode=metadata.st_mode,
            st_ino=metadata.st_ino,
            st_dev=metadata.st_dev,
            st_nlink=metadata.st_nlink,
            st_uid=0,
            st_gid=metadata.st_gid,
            st_size=metadata.st_size,
            st_mtime_ns=metadata.st_mtime_ns,
        )

    def lstat_with_root_owned_package(path: Path) -> os.stat_result | SimpleNamespace:
        metadata = real_lstat(path)
        if path in foreign_paths:
            return metadata
        return root_owned(metadata) if path == root or root in path.parents else metadata

    with patch.object(Path, "lstat", autospec=True, side_effect=lstat_with_root_owned_package), patch.object(
        server_module.os, "fstat", side_effect=lambda fd: root_owned(real_fstat(fd))
    ):
        yield


class PreflightSystemdRunner:
    def __init__(self) -> None:
        self.calls: list[tuple[str, ...]] = []

    def run(
        self,
        argv: tuple[str, ...],
        *,
        timeout_seconds: float,
        max_stdout_bytes: int,
        max_stderr_bytes: int,
    ) -> resource_cgroup.CommandResultV1:
        assert timeout_seconds > 0
        assert max_stdout_bytes > 0
        assert max_stderr_bytes > 0
        self.calls.append(argv)
        assert argv == (
            "/usr/bin/systemctl",
            "--user",
            "--no-pager",
            "show",
            "codex-master.slice",
            "--property=ControlGroup",
        )
        return resource_cgroup.CommandResultV1(
            returncode=0,
            stdout=b"ControlGroup=/user.slice/codex-master.slice\n",
            stderr=b"",
        )

    def start_held(
        self,
        argv: tuple[str, ...],
        *,
        timeout_seconds: float,
        max_stdout_bytes: int,
        max_stderr_bytes: int,
    ) -> Any:
        raise AssertionError("scope mutation is outside this test")


class RebindingSystemdRunner(PreflightSystemdRunner):
    def __init__(
        self,
        *,
        control_slice_sequence: tuple[str, ...],
        **kwargs: Any,
    ) -> None:
        super().__init__(**kwargs)
        self._control_slice_sequence = list(control_slice_sequence)
        self.control_slice_reads: list[str] = []

    def run(
        self,
        argv: tuple[str, ...],
        *,
        timeout_seconds: float,
        max_stdout_bytes: int,
        max_stderr_bytes: int,
    ) -> resource_cgroup.CommandResultV1:
        if (
            argv[0] == "/usr/bin/systemctl"
            and argv[3] == "show"
            and argv[4] == "codex-master.slice"
            and "--property=ControlGroup" in argv
        ):
            assert self._control_slice_sequence
            control_slice = self._control_slice_sequence.pop(0)
            self.calls.append(argv)
            self.control_slice_reads.append(control_slice)
            return resource_cgroup.CommandResultV1(
                returncode=0,
                stdout=f"ControlGroup={control_slice}\n".encode(),
                stderr=b"",
            )
        return super().run(
            argv,
            timeout_seconds=timeout_seconds,
            max_stdout_bytes=max_stdout_bytes,
            max_stderr_bytes=max_stderr_bytes,
        )


class HeldScopeProcess:
    def finish(
        self, *, timeout_seconds: float, max_stdout_bytes: int, max_stderr_bytes: int
    ) -> resource_cgroup.CommandResultV1:
        assert timeout_seconds > 0
        assert max_stdout_bytes > 0
        assert max_stderr_bytes > 0
        return resource_cgroup.CommandResultV1(returncode=0, stdout=b"", stderr=b"")

    def terminate(self) -> None:
        return None


class HeldScopeControl:
    instances: list["HeldScopeControl"] = []

    def __init__(self, name: str) -> None:
        self.name = name
        self.releases: list[bytes] = []
        self.closed = False

    @classmethod
    def open(cls, name: str) -> "HeldScopeControl":
        control = cls(name)
        cls.instances.append(control)
        return control

    def accept(self, *, timeout_seconds: float) -> None:
        assert timeout_seconds > 0

    def peer_pid(self) -> int:
        return 4241

    def read_challenge(self, *, expected_gate_pid: int, timeout_seconds: float) -> str:
        assert expected_gate_pid == 4241
        assert timeout_seconds > 0
        return "c" * 64

    def release_once(self, payload: bytes, *, timeout_seconds: float) -> None:
        assert timeout_seconds > 0
        self.releases.append(payload)

    def read_ready(self, *, timeout_seconds: float) -> None:
        assert timeout_seconds > 0

    def close(self) -> None:
        self.closed = True


class ScopeSystemdRunner:
    def __init__(self, cgroup_root: Path) -> None:
        self.cgroup_root = cgroup_root
        self.calls: list[tuple[str, ...]] = []
        self.started: list[tuple[str, ...]] = []
        self.stopped: list[str] = []
        self.unit_name = ""
        self.gate = HeldScopeProcess()

    @staticmethod
    def _result(
        returncode: int, *, stdout: bytes = b"", stderr: bytes = b""
    ) -> resource_cgroup.CommandResultV1:
        return resource_cgroup.CommandResultV1(
            returncode=returncode,
            stdout=stdout,
            stderr=stderr,
        )

    def run(
        self,
        argv: tuple[str, ...],
        *,
        timeout_seconds: float,
        max_stdout_bytes: int,
        max_stderr_bytes: int,
    ) -> resource_cgroup.CommandResultV1:
        assert timeout_seconds > 0
        assert max_stdout_bytes > 0
        assert max_stderr_bytes > 0
        self.calls.append(argv)
        if argv[0] == "/usr/bin/systemctl" and argv[3:5] == (
            "show",
            "codex-master.slice",
        ):
            return self._result(
                0,
                stdout=b"ControlGroup=/user.slice/codex-master.slice\n",
            )
        if argv[0] == "/usr/bin/systemctl" and (
            "--property=Id" in argv or "--property=LoadState" in argv
        ):
            return self._result(4)
        if argv[0] == "/usr/bin/systemctl" and argv[3] == "show":
            return self._result(
                0,
                stdout=(
                    f"ControlGroup=/user.slice/codex-master.slice/{self.unit_name}\n"
                    "DelegateControllers=cpu cpuset memory pids io\n"
                ).encode(),
            )
        if argv[0] == "/usr/bin/systemctl" and argv[3] == "stop":
            self.stopped.append(argv[4])
            return self._result(0)
        if argv[0] == "/usr/bin/tmux":
            return self._result(0, stdout=b"4242\n")
        raise AssertionError(f"unexpected command {argv!r}")

    def start_held(
        self,
        argv: tuple[str, ...],
        *,
        timeout_seconds: float,
        max_stdout_bytes: int,
        max_stderr_bytes: int,
    ) -> HeldScopeProcess:
        assert timeout_seconds > 0
        assert max_stdout_bytes == 65
        assert max_stderr_bytes > 0
        self.started.append(argv)
        self.unit_name = next(
            argument.split("=", 1)[1] for argument in argv if argument.startswith("--unit=")
        )
        scope_root = self.cgroup_root / "user.slice" / "codex-master.slice" / self.unit_name
        scope_root.mkdir()
        documents = {
            "cpuset.cpus.effective": b"4-11\n",
            "cpu.max": b"750000 100000\n",
            "memory.high": f"{9 * 1024**3}\n".encode(),
            "memory.max": f"{12 * 1024**3}\n".encode(),
            "memory.swap.max": f"{8 * 1024**3}\n".encode(),
            "io.weight": b"default 50\n",
            "cgroup.procs": b"4241\n4242\n4243\n",
        }
        for name, payload in documents.items():
            (scope_root / name).write_bytes(payload)
        return self.gate


def regular_systemd_adapter_for_test(
    directory: Path,
    *,
    runner: Any | None = None,
    controllers: bytes = b"cpu cpuset memory pids io\n",
    subtree_controllers: bytes = b"cpu cpuset memory pids io\n",
) -> tuple[resource_cgroup.SystemdUserCgroupAdapter, Any]:
    cgroup_root = write_cgroup_preflight_facts_for_test(
        directory,
        controllers=controllers,
        subtree_controllers=subtree_controllers,
    )
    runner = runner or PreflightSystemdRunner()
    with patch.object(resource_cgroup, "CGROUP_ROOT", cgroup_root):
        adapter = resource_cgroup.SystemdUserCgroupAdapter(runner=runner)
    return adapter, runner


def write_cgroup_preflight_facts_for_test(
    directory: Path,
    *,
    controllers: bytes = b"cpu cpuset memory pids io\n",
    subtree_controllers: bytes = b"cpu cpuset memory pids io\n",
    parent_cpuset: bytes = b"0-11\n",
    io_pressure: bytes = (
        b"some avg10=0.00 avg60=0.00 avg300=0.00 total=0\n"
        b"full avg10=0.00 avg60=0.00 avg300=0.00 total=0\n"
    ),
) -> Path:
    cgroup_root = directory / "cgroup"
    slice_root = cgroup_root / "user.slice" / "codex-master.slice"
    slice_root.mkdir(parents=True)
    (slice_root / "cgroup.controllers").write_bytes(controllers)
    (slice_root / "cgroup.subtree_control").write_bytes(subtree_controllers)
    (slice_root / "cpuset.cpus.effective").write_bytes(parent_cpuset)
    (slice_root / "io.pressure").write_bytes(io_pressure)
    return cgroup_root


def write_provider_cpu_topology_for_test(
    directory: Path,
    *,
    present: bytes = b"0-11\n",
) -> Path:
    cpu_root = directory / "cpu"
    (cpu_root / "present").parent.mkdir(parents=True)
    (cpu_root / "present").write_bytes(present)
    for cpu in range(12):
        topology_root = cpu_root / f"cpu{cpu}" / "topology"
        topology_root.mkdir(parents=True)
        (topology_root / "physical_package_id").write_bytes(b"0\n")
        (topology_root / "core_id").write_bytes(f"{cpu}\n".encode())
        (topology_root / "core_type").write_bytes(
            b"efficiency\n" if cpu >= 4 else b"performance\n"
        )
    return cpu_root


@contextlib.contextmanager
def approved_provider_facts_for_test(
    directory: Path,
    *,
    runner: Any | None = None,
    present: bytes = b"0-11\n",
    controllers: bytes = b"cpu cpuset memory pids io\n",
    subtree_controllers: bytes = b"cpu cpuset memory pids io\n",
    parent_cpuset: bytes = b"0-11\n",
) -> Any:
    cgroup_root = write_cgroup_preflight_facts_for_test(
        directory,
        controllers=controllers,
        subtree_controllers=subtree_controllers,
        parent_cpuset=parent_cpuset,
    )
    cpu_root = write_provider_cpu_topology_for_test(directory, present=present)
    runner = runner or PreflightSystemdRunner()

    def sysconf(name: str) -> int:
        if name == "SC_PAGE_SIZE":
            return 4096
        if name == "SC_PHYS_PAGES":
            return 4_194_304
        raise AssertionError(f"unexpected sysconf fact {name!r}")

    with patch.object(resource_cgroup, "CGROUP_ROOT", cgroup_root), patch.object(
        resource_cgroup, "CPU_TOPOLOGY_ROOT", cpu_root
    ), patch.object(
        resource_cgroup, "CPU_PRESENT_PATH", cpu_root / "present"
    ), patch.object(
        resource_cgroup, "_SubprocessSystemdUserRunner", return_value=runner
    ), patch.object(resource_cgroup.os, "sysconf", side_effect=sysconf):
        yield runner


def approved_cgroup_runtime_for_test(
    directory: Path,
    *,
    runner: Any | None = None,
) -> tuple[Any, resource_cgroup.SystemdUserCgroupAdapter, Any]:
    with approved_provider_facts_for_test(directory, runner=runner) as runner:
        approved = resource_cgroup.build_approved_cgroup_runtime(
            runner=runner,
            mem_total_bytes=16 * 1024**3,
        )
    return approved, approved.adapter, runner


