    def test_updated_mcp_startup_timeout_config_updates_or_inserts_value(self) -> None:
        existing_low = "\n".join(
            [
                '[projects."/tmp/example"]',
                'trust_level = "trusted"',
                "",
                "[mcp_servers.codex-master-mcp]",
                'command = "/tmp/codex-master-mcp"',
                "startup_timeout_sec = 30",
                'default_tools_approval_mode = "approve"',
                "",
                "[features]",
                "memories = true",
            ]
        )
        updated, changed, previous = updated_mcp_startup_timeout_config(existing_low)
        self.assertTrue(changed)
        self.assertEqual(previous, 30)
        self.assertIn("startup_timeout_sec = 120", updated)
        self.assertIn("[features]", updated)

        existing_high = existing_low.replace("startup_timeout_sec = 30", "startup_timeout_sec = 180")
        high_updated, high_changed, high_previous = updated_mcp_startup_timeout_config(existing_high)
        self.assertFalse(high_changed)
        self.assertEqual(high_previous, 180)
        self.assertIn("startup_timeout_sec = 180", high_updated)

        existing_float = existing_low.replace("startup_timeout_sec = 30", "startup_timeout_sec = 120.0")
        float_updated, float_changed, float_previous = updated_mcp_startup_timeout_config(existing_float)
        self.assertFalse(float_changed)
        self.assertEqual(float_previous, 120)
        self.assertEqual(float_updated.count("startup_timeout_sec"), 1)

        existing_underscored = existing_low.replace("startup_timeout_sec = 30", "startup_timeout_sec = 1_2_0")
        underscored_updated, underscored_changed, underscored_previous = updated_mcp_startup_timeout_config(
            existing_underscored
        )
        self.assertFalse(underscored_changed)
        self.assertEqual(underscored_previous, 120)
        self.assertEqual(underscored_updated.count("startup_timeout_sec"), 1)

        existing_quoted = existing_low.replace("startup_timeout_sec = 30", '"startup_timeout_sec" = 30')
        quoted_updated, quoted_changed, quoted_previous = updated_mcp_startup_timeout_config(existing_quoted)
        self.assertTrue(quoted_changed)
        self.assertEqual(quoted_previous, 30)
        self.assertEqual(quoted_updated.count("startup_timeout_sec"), 1)

        existing_exponent = existing_low.replace("startup_timeout_sec = 30", "startup_timeout_sec = 1.2e2")
        exponent_updated, exponent_changed, exponent_previous = updated_mcp_startup_timeout_config(existing_exponent)
        self.assertFalse(exponent_changed)
        self.assertEqual(exponent_previous, 120)
        self.assertEqual(exponent_updated.count("startup_timeout_sec"), 1)

        existing_non_finite = existing_low.replace("startup_timeout_sec = 30", "startup_timeout_sec = 1e999")
        finite_updated, finite_changed, finite_previous = updated_mcp_startup_timeout_config(existing_non_finite)
        self.assertTrue(finite_changed)
        self.assertIsNone(finite_previous)
        self.assertIn("startup_timeout_sec = 120", finite_updated)

        missing_value = existing_low.replace("\nstartup_timeout_sec = 30", "")
        inserted, inserted_changed, inserted_previous = updated_mcp_startup_timeout_config(missing_value)
        self.assertTrue(inserted_changed)
        self.assertIsNone(inserted_previous)
        self.assertEqual(
            tomllib.loads(inserted)["mcp_servers"]["codex-master-mcp"]["startup_timeout_sec"],
            120,
        )

        commented_header = existing_low.replace(
            "[mcp_servers.codex-master-mcp]", "[mcp_servers.codex-master-mcp] # keep this section"
        )
        commented_updated, commented_changed, _commented_previous = updated_mcp_startup_timeout_config(commented_header)
        self.assertTrue(commented_changed)
        self.assertEqual(commented_updated.count("[mcp_servers.codex-master-mcp]"), 1)
        self.assertIn("startup_timeout_sec = 120", commented_updated)

        array_table = "\n".join(
            [
                "[mcp_servers.codex-master-mcp]",
                'command = "/tmp/codex-master-mcp"',
                "",
                "[[mcp_servers.codex-master-mcp.extra]]",
                'name = "extra"',
            ]
        )
        array_updated, array_changed, _array_previous = updated_mcp_startup_timeout_config(array_table)
        self.assertTrue(array_changed)
        self.assertLess(array_updated.index("startup_timeout_sec = 120"), array_updated.index("[["))

        quoted_header = array_table.replace(
            "[mcp_servers.codex-master-mcp]", '[mcp_servers."codex-master-mcp"]'
        )
        quoted_header_updated, quoted_header_changed, _quoted_header_previous = updated_mcp_startup_timeout_config(
            quoted_header
        )
        self.assertTrue(quoted_header_changed)
        self.assertEqual(quoted_header_updated.count('[mcp_servers."codex-master-mcp"]'), 1)
        self.assertLess(quoted_header_updated.index("startup_timeout_sec = 120"), quoted_header_updated.index("[["))

        from tomllib import loads

        single_quoted_header = array_table.replace(
            "[mcp_servers.codex-master-mcp]", "[mcp_servers.'codex-master-mcp']"
        )
        single_quoted_updated, single_quoted_changed, _single_quoted_previous = (
            updated_mcp_startup_timeout_config(single_quoted_header)
        )
        self.assertTrue(single_quoted_changed)
        self.assertEqual(
            loads(single_quoted_updated)["mcp_servers"]["codex-master-mcp"]["startup_timeout_sec"],
            120,
        )

        spaced_header = array_table.replace(
            "[mcp_servers.codex-master-mcp]", "[ mcp_servers . 'codex-master-mcp' ]"
        )
        spaced_updated, spaced_changed, _spaced_previous = updated_mcp_startup_timeout_config(spaced_header)
        self.assertTrue(spaced_changed)
        self.assertEqual(loads(spaced_updated)["mcp_servers"]["codex-master-mcp"]["startup_timeout_sec"], 120)

        dotted_config = (
            'mcp_servers."codex-master-mcp".command = "/tmp/codex-master-mcp"\n'
            'mcp_servers."codex-master-mcp".startup_timeout_sec = 30\n'
        )
        dotted_updated, dotted_changed, dotted_previous = updated_mcp_startup_timeout_config(dotted_config)
        self.assertTrue(dotted_changed)
        self.assertEqual(dotted_previous, 30)
        self.assertEqual(loads(dotted_updated)["mcp_servers"]["codex-master-mcp"]["startup_timeout_sec"], 120)

        inline_config = (
            'mcp_servers = { "codex-master-mcp" = '
            '{ command = "/tmp/codex-master-mcp", startup_timeout_sec = 30 } }\n'
        )
        inline_updated, inline_changed, inline_previous = updated_mcp_startup_timeout_config(inline_config)
        self.assertTrue(inline_changed)
        self.assertEqual(inline_previous, 30)
        self.assertEqual(loads(inline_updated)["mcp_servers"]["codex-master-mcp"]["startup_timeout_sec"], 120)

        for literal, expected_changed, expected_previous in (
            ("0x78", False, 120),
            ("0o170", False, 120),
            ("0b1111000", False, 120),
            ("inf", True, None),
            ("nan", True, None),
        ):
            numeric_config = existing_low.replace("startup_timeout_sec = 30", f"startup_timeout_sec = {literal}")
            numeric_updated, numeric_changed, numeric_previous = updated_mcp_startup_timeout_config(
                numeric_config
            )
            self.assertEqual(numeric_changed, expected_changed)
            self.assertEqual(numeric_previous, expected_previous)
            self.assertEqual(
                loads(numeric_updated)["mcp_servers"]["codex-master-mcp"]["startup_timeout_sec"],
                120,
            )

        for invalid_literal in ('"120"', "true", "[120]"):
            invalid_config = existing_low.replace("startup_timeout_sec = 30", f"startup_timeout_sec = {invalid_literal}")
            invalid_updated, invalid_changed, invalid_previous = updated_mcp_startup_timeout_config(invalid_config)
            self.assertTrue(invalid_changed)
            self.assertIsNone(invalid_previous)
            self.assertEqual(
                loads(invalid_updated)["mcp_servers"]["codex-master-mcp"]["startup_timeout_sec"],
                120,
            )

        for multiline_literal in (
            "startup_timeout_sec = [\n120,\n]",
            'startup_timeout_sec = """\n120\n"""',
        ):
            multiline_config = existing_low.replace("startup_timeout_sec = 30", multiline_literal)
            multiline_updated, multiline_changed, multiline_previous = updated_mcp_startup_timeout_config(
                multiline_config
            )
            self.assertTrue(multiline_changed)
            self.assertIsNone(multiline_previous)
            self.assertEqual(
                loads(multiline_updated)["mcp_servers"]["codex-master-mcp"]["startup_timeout_sec"],
                120,
            )

