    def test_fleet_overview_local_admin_orders_lock_clock_snapshot_inventory_build(self) -> None:
        events: list[str] = []
        snapshot = _overview_cli_test_snapshot()
        inventory = object()
        overview = object()
        evidence = UsageEvidenceV2((), "unavailable", None, None)
        usage_snapshot = UsageSnapshot((), "unavailable", True, ("usage_unavailable",))
        service = Mock()

        def registry_snapshot() -> object:
            events.append("snapshot")
            return snapshot

        def inventory_builder(seen_snapshot: object, seen_pool: Path) -> object:
            self.assertIs(seen_snapshot, snapshot)
            self.assertEqual(seen_pool, server_module.AGENT_POOL_ROOT)
            events.append("inventory")
            return inventory

        def overview_builder(
            seen_snapshot: object,
            seen_inventory: object,
            *,
            created_at: datetime,
            contexts: object,
            active_only: bool,
        ) -> object:
            self.assertIs(seen_snapshot, snapshot)
            self.assertIs(seen_inventory, inventory)
            self.assertEqual(created_at, datetime(2026, 8, 15, tzinfo=timezone.utc))
            self.assertIsNone(contexts)
            self.assertTrue(active_only)
            events.append("overview")
            return overview

        def renderer(seen_overview: object, *, format: str) -> str:
            self.assertIs(seen_overview, overview)
            self.assertEqual(format, "compact")
            events.append("renderer")
            return "rendered-compact"

        def enrich(seen_overview: object, usage: object) -> object:
            self.assertIs(seen_overview, overview)
            self.assertIs(usage, usage_snapshot)
            events.append("enrich")
            return overview

        def read_usage(*, clock: object) -> UsageEvidenceV2:
            self.assertTrue(callable(clock))
            events.append("usage")
            return evidence

        def display(
            evidence_arg: UsageEvidenceV2, *, known_account_ids: frozenset[str]
        ) -> UsageSnapshot:
            self.assertIs(evidence_arg, evidence)
            self.assertEqual(known_account_ids, frozenset({"overview-account"}))
            events.append("display")
            return usage_snapshot

        service.registry_snapshot.side_effect = registry_snapshot

        @contextlib.contextmanager
        def fake_lock(_path: Path):
            events.append("lock-enter")
            try:
                yield
            finally:
                events.append("lock-exit")

        created_at = datetime(2026, 8, 15, tzinfo=timezone.utc)
        with (
            tempfile.TemporaryDirectory() as temporary,
            patch.object(server_module, "STATE_ROOT", Path(temporary) / "state"),
            patch.object(server_module, "AGENT_POOL_ROOT", Path(temporary) / "pool"),
            patch.object(server_module, "_fleet_registry_read_lock", fake_lock),
            patch.object(
                server_module, "_readonly_fleet_service", return_value=service
            ),
            patch.object(
                server_module,
                "build_inventory",
                side_effect=inventory_builder,
            ),
            patch.object(
                server_module,
                "build_fleet_overview",
                side_effect=overview_builder,
            ),
            patch.object(
                server_module,
                "read_usage_evidence_v2",
                side_effect=read_usage,
            ) as reader,
            patch.object(
                server_module,
                "derive_limit_decisions",
            ) as tracker,
            patch.object(
                server_module,
                "display_snapshot_from_evidence",
                side_effect=display,
            ),
            patch.object(
                server_module,
                "enrich_fleet_overview_usage",
                side_effect=enrich,
            ),
            patch.object(
                server_module,
                "render_fleet_overview",
                side_effect=renderer,
            ),
        ):
            result = server_module._fleet_overview_local_admin(
                active_only=True,
                format="compact",
                clock=lambda: (events.append("clock") or created_at),
            )

        self.assertEqual(result, "rendered-compact")
        self.assertEqual(
            events,
            [
                "lock-enter",
                "clock",
                "snapshot",
                "inventory",
                "overview",
                "lock-exit",
                "usage",
                "display",
                "enrich",
                "renderer",
            ],
        )
        reader.assert_called_once()
        tracker.assert_not_called()

