    def test_fleet_executable_swap_before_artifact_build_fails_closed(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            state = root / "state"
            pool = root / "pool"
            executable = root / "runner"
            replacement = root / "replacement"
            executable.write_text("#!/usr/bin/bash\nexit 0\n", encoding="utf-8")
            replacement.write_text("#!/usr/bin/bash\nexit 9\n", encoding="utf-8")
            executable.chmod(0o700)
            replacement.chmod(0o700)
            original = root / "original"
            real_artifacts = server_module._fleet_home_artifacts
            swapped = False

            def swap_then_build(*args, **kwargs):
                nonlocal swapped
                if not swapped:
                    executable.rename(original)
                    replacement.rename(executable)
                    swapped = True
                return real_artifacts(*args, **kwargs)

            with patch.object(server_module, "STATE_ROOT", state), patch.object(
                server_module, "AGENT_POOL_ROOT", pool
            ), patch.object(server_module, "_fleet_home_artifacts", side_effect=swap_then_build):
                with self.assertRaisesRegex(AgentError, "fleet_executable_changed"):
                    server_module.fleet_series_apply(
                        prefix="d", count=1, runner="codex_cli", provider="ollama_local",
                        model="local-model", account_id=None, expected_generation=1,
                        codex_executable=executable,
                    )

            self.assertFalse((pool / "d1").exists())

    def test_fleet_home_target_uses_one_projection_and_exact_provider_files(self) -> None:
        common = (
            Path(server_module.__file__).with_name("markdown") / "common.md"
        ).read_bytes()
        base_marker_fields = {
            "schema_version",
            "kind",
            "agent_id",
            "prefix",
            "runner",
            "provider",
            "model",
            "common_policy",
            "managed_files",
            "files",
        }
        for runner in (
            server_module.RunnerKind.CODEX_CLI,
            server_module.RunnerKind.GEMINI_CLI,
        ):
            with self.subTest(runner=runner.value), tempfile.TemporaryDirectory() as tmp:
                root = Path(tmp)
                home = root / "pool" / "a1"
                executable = root / (
                    "gemini-native"
                    if runner is server_module.RunnerKind.GEMINI_CLI
                    else "codex-native"
                )
                descriptor = server_module.AgentDescriptor(
                    agent_id="a1",
                    series_prefix="a",
                    ordinal=1,
                    label="Agentin A1",
                    runner=runner,
                    provider=(
                        server_module.Provider.GEMINI_API
                        if runner is server_module.RunnerKind.GEMINI_CLI
                        else server_module.Provider.OPENAI_CHATGPT
                    ),
                    model="test-model",
                    account_id=(
                        "gemini-project-1"
                        if runner is server_module.RunnerKind.GEMINI_CLI
                        else None
                    ),
                    home=home,
                    session="session-a1",
                    enabled=True,
                    runner_path=home / (
                        "gemini"
                        if runner is server_module.RunnerKind.GEMINI_CLI
                        else "codex"
                    ),
                    skill_profile="teamleiterin",
                )
                real_projection = server_module.fleet_markdown_projection
                with patch.object(
                    server_module,
                    "fleet_markdown_projection",
                    wraps=real_projection,
                ) as projection:
                    target = server_module._build_fleet_home_target(
                        descriptor,
                        executable,
                        include_portable_skills=False,
                    )

                projection.assert_called_once()
                files = {
                    name: (content, mode)
                    for name, content, mode in target.files
                }
                expected_files = (
                    {
                        "gemini",
                        ".gemini/settings.json",
                        ".gemini/GEMINI.md",
                        ".gemini/AGENTS.class-teamleiterin.md",
                        ".gemini/policies/codex-master.toml",
                    }
                    if runner is server_module.RunnerKind.GEMINI_CLI
                    else {
                        "codex",
                        "config.toml",
                        "AGENTS.md",
                        "AGENTS.class-teamleiterin.md",
                    }
                )
                primary_name = (
                    ".gemini/GEMINI.md"
                    if runner is server_module.RunnerKind.GEMINI_CLI
                    else "AGENTS.md"
                )
                class_names = {
                    name
                    for name in files
                    if re.search(r"(?:^|/)AGENTS\.class-[a-z0-9_-]+\.md$", name)
                }
                marker = json.loads(target.marker_bytes.decode("utf-8"))

                self.assertEqual(set(files), expected_files)
                self.assertEqual(len(class_names), 1)
                self.assertNotIn("settings.json", files)
                if runner is server_module.RunnerKind.GEMINI_CLI:
                    self.assertNotIn("AGENTS.md", files)
                self.assertTrue(files[primary_name][0].startswith(common))
                self.assertEqual(marker["common_policy"], canonical_common_policy_marker_for_test())
                self.assertEqual(set(marker), base_marker_fields)
                self.assertEqual(marker["managed_files"], sorted(expected_files))
                self.assertEqual(
                    marker["files"],
                    {
                        name: hashlib.sha256(content).hexdigest()
                        for name, (content, _mode) in sorted(files.items())
                    },
                )
                self.assertEqual(
                    target.provider_projection_digest,
                    hashlib.sha256(files[primary_name][0]).hexdigest(),
                )
                repeated = server_module._build_fleet_home_target(
                    descriptor,
                    executable,
                    include_portable_skills=False,
                )
                self.assertEqual(repeated, target)

