        mock_run.side_effect = subprocess.TimeoutExpired(["git", "status"], DEFAULT_COMMAND_TIMEOUT_SECONDS)

        result = run_command(["git", "status"])

        self.assertEqual(result.returncode, COMMAND_TIMEOUT_RETURN_CODE)
