    def test_initialize_rejects_unsupported_protocol(self) -> None:
        response = handle_rpc(
            {"jsonrpc": "2.0", "id": 10, "method": "initialize", "params": {"protocolVersion": "2025-12-31"}}
        )
        self.assertIsNotNone(response)
        self.assertEqual(response["id"], 10)
        self.assertEqual(response["error"]["code"], -32602)
        self.assertEqual(response["error"]["message"], "Unsupported protocol version")

    def test_initialize_rejects_non_object_params(self) -> None:
        for index, value in enumerate(([], False, 0, "", ["unexpected"]), start=1):
            response = handle_rpc({"jsonrpc": "2.0", "id": 100 + index, "method": "initialize", "params": value})

            self.assertEqual(response["error"]["code"], -32602)
            self.assertEqual(response["error"]["message"], "initialize params must be an object")

    def test_initialize_accepts_supported_protocol(self) -> None:
        response = handle_rpc(
            {"jsonrpc": "2.0", "id": 16, "method": "initialize", "params": {"protocolVersion": "2025-11-25"}}
        )

        result = response["result"]
        self.assertEqual(result["protocolVersion"], "2025-11-25")
        self.assertEqual(result["serverInfo"]["name"], "codex-master-mcp")
        self.assertIn("tools", result["capabilities"])
        self.assertIn("resources", result["capabilities"])
        self.assertIn("prompts", result["capabilities"])

    def test_mcp_resources_and_prompts_list_empty(self) -> None:
        resources = handle_rpc({"jsonrpc": "2.0", "id": 11, "method": "resources/list"})
        prompts = handle_rpc({"jsonrpc": "2.0", "id": 12, "method": "prompts/list"})

        self.assertIsNotNone(resources)
        self.assertEqual(resources["result"], {"resources": []})
        self.assertEqual(prompts["result"], {"prompts": []})

    def test_handle_rpc_distinguishes_notifications_from_null_id(self) -> None:
        for method in ("initialize", "tools/list", "resources/list", "prompts/list"):
            self.assertIsNone(handle_rpc({"jsonrpc": "2.0", "method": method}))

        response = handle_rpc({"jsonrpc": "2.0", "id": None, "method": "tools/list"})

        self.assertIsNotNone(response)
        self.assertIsNone(response["id"])

    def test_read_message_rejects_oversized_content_length(self) -> None:
        data = f"Content-Length: {MAX_RPC_MESSAGE_BYTES + 1}\r\n\r\n".encode("ascii")
        with patch("sys.stdin", FakeStdin(data)):
            with self.assertRaisesRegex(AgentError, "Content-Length exceeds"):
                read_message()

    def test_read_message_rejects_oversized_content_length_header_block(self) -> None:
        header_line = b"X: " + (b"x" * (64 * 1024 - 5)) + b"\r\n"
        data = b"Content-Length: 2\r\n" + (header_line * 17) + b"\r\n{}"
        with patch("sys.stdin", FakeStdin(data)):
            with self.assertRaisesRegex(AgentError, "RPC header block exceeds"):
                read_message()

    def test_read_message_rejects_oversized_json_line(self) -> None:
        data = b"{" + (b"x" * MAX_RPC_MESSAGE_BYTES)
        with patch("sys.stdin", FakeStdin(data)):
            with self.assertRaisesRegex(AgentError, "RPC message line exceeds"):
                read_message()

    def test_read_message_rejects_incomplete_content_body(self) -> None:
        with patch("sys.stdin", FakeStdin(b"Content-Length: 20\r\n\r\n{}")):
            with self.assertRaisesRegex(AgentError, "incomplete RPC message body"):
                read_message()

    def test_read_message_rejects_json_null_messages(self) -> None:
        messages = (b"null\n", b"Content-Length: 4\r\n\r\nnull")
        for data in messages:
            with self.subTest(data=data), patch("sys.stdin", FakeStdin(data)):
                with self.assertRaisesRegex(AgentError, "RPC message must be an object"):
                    read_message()

    def test_read_message_skips_blank_lines_before_json_message(self) -> None:
        message = {"jsonrpc": "2.0", "id": 1, "method": "resources/list"}
        data = b"\n  \n" + json.dumps(message).encode("utf-8") + b"\n"

        with patch("sys.stdin", FakeStdin(data)):
            self.assertEqual(read_message(), message)

    def test_read_message_accepts_case_insensitive_content_length(self) -> None:
        message = {"jsonrpc": "2.0", "id": 1, "method": "resources/list"}
        body = json.dumps(message).encode("utf-8")

        with patch("sys.stdin", FakeStdin(b"content-length: " + str(len(body)).encode("ascii") + b"\r\n\r\n" + body)):
            self.assertEqual(read_message(), message)

    def test_read_message_accepts_content_length_after_content_type(self) -> None:
        message = {"jsonrpc": "2.0", "id": 1, "method": "resources/list"}
        body = json.dumps(message).encode("utf-8")
        data = b"Content-Type: application/json\r\nContent-Length: " + str(len(body)).encode("ascii") + b"\r\n\r\n" + body

        with patch("sys.stdin", FakeStdin(data)):
            self.assertEqual(read_message(), message)

    def test_write_message_uses_newline_delimited_stdio_framing(self) -> None:
        payload = {"jsonrpc": "2.0", "id": 1, "result": {"text": "café"}}
        stdout = Mock()
        stdout.buffer = io.BytesIO()

        with patch("sys.stdout", stdout):
            server_module.write_message(payload)

        self.assertEqual(
            stdout.buffer.getvalue(),
            json.dumps(payload, ensure_ascii=True, separators=(",", ":")).encode("utf-8") + b"\n",
        )

