    def test_watchdog_marker_requires_same_assignment_identity(self) -> None:
        marker = {
            "phase": "report_requested",
            "planned_action": "interrupt",
            "assignment_id": "old-assignment",
            "requested_at_utc": "2026-06-07T10:00:00+00:00",
            "started_at_utc": "2026-06-07T09:00:00+00:00",
        }

        self.assertTrue(
            watchdog_marker_matches(
                marker,
                action="interrupt",
                assignment_id="old-assignment",
                session_started_at="2026-06-07T09:00:00+00:00",
            )
        )
        lease_marker = {**marker, "lease_id": "lease-old"}
        self.assertTrue(
            watchdog_marker_matches(
                lease_marker,
                action="interrupt",
                assignment_id="old-assignment",
                session_started_at="2026-06-07T09:00:00+00:00",
                lease_id="lease-old",
            )
        )
        self.assertFalse(
            watchdog_marker_matches(
                lease_marker,
                action="interrupt",
                assignment_id="old-assignment",
                session_started_at="2026-06-07T09:00:00+00:00",
                lease_id="lease-new",
            )
        )
        self.assertFalse(
            watchdog_marker_matches(
                marker,
                action="interrupt",
                assignment_id="old-assignment",
                session_started_at="2026-06-07T09:30:00+00:00",
            )
        )
        self.assertFalse(watchdog_marker_matches(marker, action="interrupt", assignment_id=None))
        self.assertFalse(watchdog_marker_matches(marker, action="interrupt", assignment_id="new-assignment"))
        invalid_time = {**marker, "requested_at_utc": "not-a-timestamp"}
        self.assertFalse(
            watchdog_marker_matches(
                invalid_time,
                action="interrupt",
                assignment_id="old-assignment",
                session_started_at="2026-06-07T09:00:00+00:00",
            )
        )
        future_time = {**marker, "requested_at_utc": "2099-01-01T00:00:00+00:00"}
        self.assertFalse(
            watchdog_marker_matches(
                future_time,
                action="interrupt",
                assignment_id="old-assignment",
                session_started_at="2026-06-07T09:00:00+00:00",
                now=1780826400.0,
            )
        )

