    def test_prune_raw_logs_rejects_raw_root_swap_before_scan(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            tmp_path = Path(tmpdir)
            raw_dir = tmp_path / "raw"
            backup_raw = tmp_path / "raw-backup"
            redirected_raw = tmp_path / "redirected-raw"
            raw_dir.mkdir()
            redirected_raw.mkdir()
            for index in range(2):
                log_path = redirected_raw / f"outside-{index}.log"
                log_path.write_bytes(b"x" * 200)
                os.utime(log_path, (1000 + index, 1000 + index))
            swapped = False

            def real_is_real(path: Path) -> bool:
                try:
                    return stat.S_ISDIR(path.lstat().st_mode)
                except OSError:
                    return False

            def swap_after_check(path: Path) -> bool:
                nonlocal swapped
                if path == raw_dir and not swapped:
                    swapped = True
                    raw_dir.rename(backup_raw)
                    raw_dir.symlink_to(redirected_raw, target_is_directory=True)
                    return True
                return real_is_real(path)

            with patch("codex_master.server.RAW_DIR", raw_dir), patch(
                "codex_master.server.LEGACY_STATE_ROOT", tmp_path / "legacy"
            ), patch("codex_master.server.META_DIR", tmp_path / "meta"), patch(
                "codex_master.server.LEGACY_META_DIR", tmp_path / "legacy" / "meta"
            ), patch("codex_master.server.is_real_directory_no_symlink", side_effect=swap_after_check):
                prune_raw_logs(max_files=1, max_bytes=80)
            redirected_sizes = sorted(path.stat().st_size for path in redirected_raw.glob("*.log"))
            redirected_names = sorted(path.name for path in redirected_raw.glob("*.log"))
            redirected_modes = sorted(stat.S_IMODE(path.stat().st_mode) for path in redirected_raw.glob("*.log"))

        self.assertTrue(swapped)
        self.assertEqual(redirected_names, ["outside-0.log", "outside-1.log"])
        self.assertEqual(redirected_sizes, [200, 200])
        self.assertEqual(redirected_modes, [0o644, 0o644])

    def test_prune_raw_logs_rejects_log_swap_before_unlink(self) -> None:
        from codex_master import server as server_module

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            raw_dir = root / "raw"
            raw_dir.mkdir()
            old_log = raw_dir / "old.log"
            newest_log = raw_dir / "newest.log"
            backup_log = root / "old-original.log"
            outside_log = root / "outside.log"
            old_log.write_bytes(b"managed-old\n")
            newest_log.write_bytes(b"managed-newest\n")
            outside_log.write_bytes(b"external-secret\n")
            os.utime(old_log, (1000, 1000))
            os.utime(newest_log, (1001, 1001))
            real_harden = server_module.harden_raw_log_at_dir_fd

            def swap_before_unlink(directory_fd, name, expected_stat):
                if name == old_log.name and old_log.exists():
                    old_log.rename(backup_log)
                    outside_log.rename(old_log)
                return real_harden(directory_fd, name, expected_stat)

            with patch("codex_master.server.RAW_DIR", raw_dir), patch(
                "codex_master.server.LEGACY_STATE_ROOT", root / "legacy"
            ), patch("codex_master.server.harden_raw_log_at_dir_fd", side_effect=swap_before_unlink):
                result = server_module.prune_raw_logs(max_files=1, max_bytes=80)

            external_content = old_log.read_text(encoding="utf-8")
            original_exists = backup_log.exists()

        self.assertEqual(result["deleted_count"], 0)
        self.assertEqual(external_content, "external-secret\n")
        self.assertTrue(original_exists)

    def test_bound_raw_log_at_dir_fd_rejects_path_swap_before_replace(self) -> None:
        from codex_master import server as server_module

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            raw_dir = root / "raw"
            raw_dir.mkdir()
            target = raw_dir / "agent.log"
            attacker = raw_dir / "attacker.log"
            target.write_bytes(b"managed" * 20)
            attacker.write_bytes(b"attacker\n")
            raw_stat = raw_dir.lstat()
            raw_fd = server_module.open_directory_no_follow_matching(
                raw_dir,
                raw_stat,
                error_text="raw log directory unreadable",
                changed_text="raw log directory changed",
            )
            real_fdopen = server_module.os.fdopen
            swapped = False

            def swap_before_tail_read(path: int, mode: str = "r", *args: Any, **kwargs: Any):
                nonlocal swapped
                fh = real_fdopen(path, mode, *args, **kwargs)

                class _ReadSwapFile:
                    def __enter__(self):
                        return self

                    def __exit__(self, exc_type, exc, tb):
                        return fh.__exit__(exc_type, exc, tb)

                    def seek(self, *seek_args: Any, **seek_kwargs: Any):
                        return fh.seek(*seek_args, **seek_kwargs)

                    def close(self) -> None:
                        return fh.close()

                    def read(self, length: int = -1) -> bytes:
                        nonlocal swapped
                        if not swapped:
                            swapped = True
                            server_module.os.rename(
                                attacker.name,
                                target.name,
                                src_dir_fd=raw_fd,
                                dst_dir_fd=raw_fd,
                            )
                        return fh.read(length)

                    def __getattr__(self, name: str) -> Any:
                        return getattr(fh, name)

                return _ReadSwapFile()

            with patch.object(server_module.os, "fdopen", side_effect=swap_before_tail_read):
                result = server_module.bound_raw_log_at_dir_fd(raw_fd, target.name, max_bytes=10)

            server_module.os.close(raw_fd)

            self.assertTrue(swapped)
            self.assertFalse(result)
            self.assertEqual(target.read_text(encoding="utf-8"), "attacker\n")

    def test_cleanup_failed_start_rejects_raw_log_swap_before_unlink(self) -> None:
        from codex_master import server as server_module

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            raw_dir = root / "raw"
            raw_dir.mkdir()
            raw_log = raw_dir / "agent.log"
