    def test_agent_release_does_not_delete_newly_claimed_lease(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            state = root / "state"
            before_remove = threading.Event()
            claim_started = threading.Event()
            claim_written = threading.Event()
            claim_finished = threading.Event()
            claim_errors: list[BaseException] = []
            with patch("codex_master.server.STATE_ROOT", state), patch(
                "codex_master.server.RAW_DIR", state / "raw"
            ), patch("codex_master.server.META_DIR", state / "meta"), patch(
                "codex_master.server.LOCK_DIR", state / "locks"
            ), patch("codex_master.server.LEASE_DIR", state / "leases"), patch(
                "codex_master.server.SERVER_INSTANCE_ID", "owner-one"
            ):

                claim_agent("a", ttl_seconds=DEFAULT_AGENT_LEASE_SECONDS)

                def concurrent_claim() -> None:
                    before_remove.wait(1)
                    claim_started.set()
                    try:
                        claim_agent("a", ttl_seconds=DEFAULT_AGENT_LEASE_SECONDS)
                    except BaseException as exc:
                        claim_errors.append(exc)
                    finally:
                        claim_finished.set()

                def remove_after_claim_starts(agent: str) -> bool:
                    before_remove.set()
                    self.assertTrue(claim_started.wait(1))
                    claim_written.wait(1)
                    path = state / "leases" / f"{agent}.json"
                    path.unlink(missing_ok=True)
                    return True

                from codex_master import server as server_module

                real_write_agent_lease = server_module.write_agent_lease

                def write_and_signal(agent: str, ttl_seconds: int) -> dict[str, Any]:
                    record = real_write_agent_lease(agent, ttl_seconds)
                    claim_written.set()
                    return record

                worker = threading.Thread(target=concurrent_claim)
                with patch("codex_master.server.remove_agent_lease", side_effect=remove_after_claim_starts), patch(
                    "codex_master.server.write_agent_lease", side_effect=write_and_signal
                ):
                    worker.start()
                    release_agent("a", force=True)
                worker.join(1)

                self.assertTrue(claim_finished.is_set())
                self.assertEqual(claim_errors, [])
                self.assertEqual(agent_lease_status("a")["state"], "held")

    def test_direct_stop_does_not_delete_newly_claimed_lease(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            state = root / "state"
            kill_started = threading.Event()
            claim_started = threading.Event()
            claim_finished = threading.Event()
            claim_errors: list[BaseException] = []

            def fake_kill(argv: list[str], **_kwargs: Any) -> subprocess.CompletedProcess[str]:
                kill_started.set()
                return subprocess.CompletedProcess(argv, 0, "", "")

            def concurrent_claim() -> None:
                if not kill_started.wait(1):
                    claim_errors.append(AssertionError("stop did not reach tmux kill"))
                    claim_finished.set()
                    return
                claim_started.set()
                try:
                    claim_agent("a")
                except BaseException as exc:
                    claim_errors.append(exc)
                finally:
                    claim_finished.set()

            from codex_master import server as server_module

            real_release_agent = server_module.release_agent

            def release_after_claim_attempt(agent: str, force: bool = False) -> dict[str, Any]:
                if not claim_started.wait(1):
                    claim_errors.append(AssertionError("stop did not reach lease release"))
                claim_finished.wait(1)
                return real_release_agent(agent, force=force)

            with patch("codex_master.server.STATE_ROOT", state), patch(
                "codex_master.server.RAW_DIR", state / "raw"
            ), patch("codex_master.server.META_DIR", state / "meta"), patch(
                "codex_master.server.LOCK_DIR", state / "locks"
            ), patch("codex_master.server.LEASE_DIR", state / "leases"), patch(
                "codex_master.server.SERVER_INSTANCE_ID", "owner-one"
            ), patch.dict(
                "codex_master.server.AGENTS",
                {"a": {"session": "session-a", "home": root, "runner": root / "codex"}},
                clear=True,
            ), patch("codex_master.server.tmux_alive", return_value=True), patch(
                "codex_master.server.pane_pid", return_value=123
            ), patch(
                "codex_master.server.agent_home_process_summary",
                side_effect=[
                    {
                        "process_count": 1,
                        "managed_process_count": 1,
                        "managed_process_ids": [123],
                        "managed_root_process_ids": [123],
                        "external_process_count": 0,
                        "external_processes": [],
                        "external_processes_truncated": False,
                        "raw_output": "not_returned",
                    },
                    {
                        "process_count": 0,
                        "managed_process_count": 0,
                        "external_process_count": 0,
                        "external_processes": [],
                        "external_processes_truncated": False,
                        "raw_output": "not_returned",
                    },
                ],
            ), patch(
                "codex_master.server.run_tmux", side_effect=fake_kill
            ), patch(
                "codex_master.server.release_agent", side_effect=release_after_claim_attempt
            ):
                worker = threading.Thread(target=concurrent_claim)
                worker.start()
                result = stop_agent("a")
                worker.join(2)
                lease = agent_lease_status("a")

        self.assertEqual(result["status"], "stopped")
        self.assertFalse(worker.is_alive())
        self.assertEqual(claim_errors, [])
        self.assertEqual(lease["state"], "held")

    def test_direct_interrupt_serializes_lease_during_tmux_action(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            state = root / "state"
            claim_finished = threading.Event()
            release_attempted = threading.Event()
            release_finished = threading.Event()
            release_before_send: list[bool] = []
            errors: list[BaseException] = []

            def fake_claim(_agent: str) -> dict[str, Any]:
                claim_finished.set()
                return {
                    "status": "claimed",
                    "lease": {"state": "held", "held_by_this_server": True},
                }

            def fake_interrupt(argv: list[str], **_kwargs: Any) -> subprocess.CompletedProcess[str]:
                if not release_attempted.wait(1):
                    errors.append(AssertionError("release did not start during interrupt"))
                release_before_send.append(release_finished.is_set())
                return subprocess.CompletedProcess(argv, 0, "", "")

            from codex_master import server as server_module

            real_release_agent = server_module.release_agent

            def concurrent_release(agent: str, force: bool = False) -> dict[str, Any]:
                if not claim_finished.wait(1):
                    errors.append(AssertionError("interrupt did not claim lease"))
                release_attempted.set()
                try:
                    return real_release_agent(agent, force=force)
                finally:
                    release_finished.set()

            with patch("codex_master.server.STATE_ROOT", state), patch(
                "codex_master.server.RAW_DIR", state / "raw"
            ), patch("codex_master.server.META_DIR", state / "meta"), patch(
                "codex_master.server.LOCK_DIR", state / "locks"
            ), patch("codex_master.server.LEASE_DIR", state / "leases"), patch.dict(
                "codex_master.server.AGENTS",
                {"a": {"session": "session-a", "home": root, "runner": root / "codex"}},
                clear=True,
            ), patch("codex_master.server.tmux_alive", return_value=True), patch(
                "codex_master.server.pane_pid", return_value=123
            ), patch(
                "codex_master.server.agent_home_process_summary",
                return_value={
                    "process_count": 1,
                    "managed_process_count": 1,
                    "managed_process_ids": [123],
                    "managed_root_process_ids": [123],
                    "external_process_count": 0,
                    "external_processes": [],
                    "external_processes_truncated": False,
                    "raw_output": "not_returned",
                },
            ), patch(
                "codex_master.server.claim_agent", side_effect=fake_claim
            ), patch("codex_master.server.run_tmux", side_effect=fake_interrupt), patch(
                "codex_master.server.release_agent", side_effect=concurrent_release
            ):
                worker = threading.Thread(target=lambda: server_module.release_agent("a", force=True))
                worker.start()
                result = interrupt_agent("a")
                worker.join(2)

        self.assertEqual(result["status"], "interrupt_sent")
        self.assertFalse(worker.is_alive())
        self.assertEqual(errors, [])
        self.assertEqual(release_before_send, [False])

