            self.assertEqual(refreshed["hooks"]["state"][hook_ids[0]]["trusted_hash"], hook_hashes[0])
            self.assertEqual(refreshed["hooks"]["state"][hook_ids[1]]["trusted_hash"], hook_hashes[1])
