    def test_agent_pool_install_status_copy_auth_and_destroy_are_data_sparse(self) -> None:
        from codex_master import server as server_module

        with tempfile.TemporaryDirectory() as tmpdir:
            tmp = Path(tmpdir)
            pool = tmp / "agents"
            spec_path = self._write_spec(tmp, pool)
            (pool / "a1" / "skills").mkdir(parents=True)
            (pool / "a1" / "plugins").mkdir()

            validation = server_module.agent_pool_validate(str(spec_path), target_dir=str(pool), codex_bin="/bin/echo")
            self.assertTrue(validation["ok"])
            self.assertEqual(validation["expected_agent_count"], 4)
            self.assertEqual(validation["pool_root"], "not_returned")
            self.assertEqual(validation["series"], "not_returned")
            self.assertEqual(validation["series_state"], "set")
            self.assertEqual(validation["aliases"], "not_returned")
            self.assertEqual(validation["aliases_state"], "set")
            self.assertEqual(validation["authenticated_agents"], "not_returned")
            self.assertEqual(validation["authenticated_agents_state"], "set")

            install_result = server_module.agent_pool_install(str(spec_path), target_dir=str(pool), codex_bin="/bin/echo")
            self.assertTrue(install_result["ok"])
            self.assertEqual(install_result["installed_agent_count"], 4)
            self.assertTrue((pool / "a1" / "codex").is_file())
            self.assertTrue(os.access(pool / "a1" / "codex", os.X_OK))
            wrapper_text = (pool / "a1" / "codex").read_text(encoding="utf-8")
            self.assertIn(f'export CODEX_HOME="{pool / "a1"}"', wrapper_text)
            self.assertNotIn("/proc/self/fd/", wrapper_text)
            self.assertIn(f'[projects."{pool / "a1"}"]', (pool / "a1" / "config.toml").read_text(encoding="utf-8"))
            self.assertTrue((pool / "a2" / "skills").is_symlink())
            self.assertFalse((pool / "a2" / "auth.json").exists())

            (pool / "a1" / "auth.json").write_text('{"token":"secret"}\n', encoding="utf-8")
            dry_run = server_module.agent_pool_copy_auth(
                str(spec_path),
                target_dir=str(pool),
                codex_bin="/bin/echo",
                from_agent="a1",
                to="a-series",
            )
            self.assertTrue(dry_run["dry_run"])
            self.assertEqual(dry_run["source_agent"], "not_returned")
            self.assertEqual(dry_run["source_agent_state"], "set")
            self.assertEqual(dry_run["target_selector"], "not_returned")
            self.assertEqual(dry_run["target_selector_state"], "set")
            self.assertEqual(dry_run["copyable_count"], 1)
            self.assertEqual(dry_run["copied_count"], 0)
            self.assertFalse((pool / "a2" / "auth.json").exists())

            copied = server_module.agent_pool_copy_auth(
                str(spec_path),
                target_dir=str(pool),
                codex_bin="/bin/echo",
                from_agent="a1",
                to="a-series",
                yes=True,
            )
            self.assertFalse(copied["dry_run"])
            self.assertEqual(copied["copied_count"], 1)
            self.assertEqual((pool / "a2" / "auth.json").read_text(encoding="utf-8"), '{"token":"secret"}\n')
            self.assertNotIn("a-series", json.dumps(copied, sort_keys=True))

            case_insensitive = server_module.agent_pool_copy_auth(
                str(spec_path),
                target_dir=str(pool),
                codex_bin="/bin/echo",
                from_agent="A1",
                to="A-SERIES",
                yes=True,
                overwrite=True,
            )
            self.assertEqual(case_insensitive["copied_count"], 1)

            status = server_module.agent_pool_status(str(spec_path), target_dir=str(pool), codex_bin="/bin/echo")
            self.assertTrue(status["ok"])
            self.assertTrue(status["marker_present"])
            self.assertEqual(status["marker_state"], "file")
            self.assertEqual(status["existing_agent_count"], 4)
            self.assertEqual(status["config_count"], 4)
            self.assertEqual(status["shared_asset_expected_link_count"], 2)
            self.assertEqual(status["shared_asset_valid_link_count"], 2)
            self.assertEqual(status["shared_asset_missing_link_count"], 0)
            self.assertEqual(status["shared_asset_invalid_link_count"], 0)
            self.assertEqual(status["series_count"], 3)
            self.assertEqual(status["series"], "not_returned")
            self.assertEqual(status["series_state"], "set")
            self.assertEqual(status["auth_count"], 2)
            status_text = json.dumps(status, sort_keys=True)
            self.assertNotIn(str(pool), status_text)
            self.assertIn("not_returned", status_text)

            with self.assertRaises(AgentError):
                server_module.agent_pool_destroy_pool(str(spec_path), target_dir=str(pool), codex_bin="/bin/echo")

            destroyed = server_module.agent_pool_destroy_pool(
                str(spec_path),
                target_dir=str(pool),
                codex_bin="/bin/echo",
                yes=True,
                remove_root=True,
            )
            self.assertTrue(destroyed["ok"])
            self.assertEqual(destroyed["removed_agent_entries"], 4)
            self.assertFalse(pool.exists())

