    def test_agent_pool_destroy_reports_root_removal_failure(self) -> None:
        from codex_master import server as server_module

        with tempfile.TemporaryDirectory() as tmpdir:
            tmp = Path(tmpdir)
            pool = tmp / "agents"
            spec_path = self._write_spec(tmp, pool)
            server_module.agent_pool_install(str(spec_path), target_dir=str(pool), codex_bin="/bin/echo")
            (pool / "unexpected-entry").write_text("keep\n", encoding="utf-8")

            result = server_module.agent_pool_destroy_pool(
                str(spec_path),
                target_dir=str(pool),
                codex_bin="/bin/echo",
                yes=True,
                remove_root=True,
            )
            self.assertFalse(result["ok"])
            self.assertFalse(result["root_removed"])
            self.assertFalse((pool / "a1").exists())
            self.assertTrue((pool / "unexpected-entry").is_file())
            self.assertTrue((pool / server_module.POOL_MARKER_FILE).is_file())

            (pool / "unexpected-entry").unlink()
            retry = server_module.agent_pool_destroy_pool(
                str(spec_path),
                target_dir=str(pool),
                codex_bin="/bin/echo",
                yes=True,
                remove_root=True,
            )
            self.assertTrue(retry["ok"])
            self.assertTrue(retry["root_removed"])
            self.assertFalse(pool.exists())

    def test_agent_pool_destroy_does_not_overwrite_marker_created_during_restore(self) -> None:
        from codex_master import server as server_module

        with tempfile.TemporaryDirectory() as tmpdir:
            tmp = Path(tmpdir)
            pool = tmp / "agents"
            spec_path = self._write_spec(tmp, pool)
            server_module.agent_pool_install(str(spec_path), target_dir=str(pool), codex_bin="/bin/echo")
            marker = pool / server_module.POOL_MARKER_FILE
            (pool / "unexpected-entry").write_text("keep\n", encoding="utf-8")
            real_link = os.link

            def create_foreign_marker_before_link(src, dst, *args, **kwargs):
                if dst == server_module.POOL_MARKER_FILE:
                    marker.write_text("foreign marker\n", encoding="utf-8")
                return real_link(src, dst, *args, **kwargs)

            state = tmp / "state"
            with patch.object(server_module, "STATE_ROOT", state), patch.object(
                server_module, "LOCK_DIR", state / "locks"
            ), patch.object(server_module, "LEASE_DIR", state / "leases"), patch.object(
                server_module, "agent_lease_status", return_value={"state": "unclaimed"}
            ), patch.object(server_module.os, "link", side_effect=create_foreign_marker_before_link):
                with self.assertRaisesRegex(AgentError, "pool marker changed during removal"):
                    server_module.agent_pool_destroy_pool(
                        str(spec_path),
                        target_dir=str(pool),
                        codex_bin="/bin/echo",
                        yes=True,
                        remove_root=True,
                    )

            marker_text = marker.read_text(encoding="utf-8")

        self.assertEqual(marker_text, "foreign marker\n")

    def test_agent_pool_tools_are_registered_and_cli_invokes_pool_namespace(self) -> None:
        from codex_master import server as server_module

        tool_names = {tool["name"] for tool in server_module.TOOLS}
        self.assertIn("agent_pool_validate", tool_names)
        self.assertIn("agent_pool_destroy_pool", tool_names)

        captured_payloads = []

        def _capture(payload):
            captured_payloads.append(payload)
            return 0

        with tempfile.TemporaryDirectory() as tmpdir:
            tmp = Path(tmpdir)
            pool = tmp / "agents"
            spec_path = self._write_spec(tmp, pool)
            with patch("codex_master.server.print_json", side_effect=_capture):
                result = server_module.main_cli(["pool", "validate", "--spec", str(spec_path), "--target-dir", str(pool)])

        self.assertEqual(result, 0)
        self.assertEqual(len(captured_payloads), 1)
        self.assertTrue(captured_payloads[0]["ok"])
        self.assertEqual(captured_payloads[0]["pool_root"], "not_returned")

    def test_agent_pool_spec_reader_rejects_symlink_and_oversized_without_path_leak(self) -> None:
        from codex_master import server as server_module

        with tempfile.TemporaryDirectory() as tmpdir:
            tmp = Path(tmpdir)
            pool = tmp / "agents-secret"
            real_spec = self._write_spec(tmp, pool)
            link = tmp / "pool-link.json"
            link.symlink_to(real_spec.name)
            response = handle_rpc(
                {
                    "jsonrpc": "2.0",
                    "id": 64,
                    "method": "tools/call",
                    "params": {
                        "name": "agent_pool_validate",
                        "arguments": {"spec": str(link), "target_dir": str(pool)},
                    },
                }
            )

            self.assertTrue(response["result"]["isError"])
            payload_text = response["result"]["content"][0]["text"]
            self.assertIn("pool spec must be a readable regular file within the size limit", payload_text)
            self.assertNotIn(str(tmp), payload_text)
            self.assertNotIn("agents-secret", payload_text)

            oversized = tmp / "oversized-pool.json"
            oversized.write_text("x" * (server_module.MAX_POOL_SPEC_BYTES + 1), encoding="utf-8")
            response = handle_rpc(
                {
                    "jsonrpc": "2.0",
                    "id": 65,
                    "method": "tools/call",
                    "params": {
                        "name": "agent_pool_validate",
                        "arguments": {"spec": str(oversized), "target_dir": str(pool)},
                    },
                }
            )

            self.assertTrue(response["result"]["isError"])
            payload_text = response["result"]["content"][0]["text"]
            self.assertIn("pool spec must be a readable regular file within the size limit", payload_text)
            self.assertNotIn(str(tmp), payload_text)
            self.assertNotIn("agents-secret", payload_text)


